// Session19/Session19InheritanceDemo.cs
public sealed class Session19InheritanceDemo
{
    public void Run()
    {
        Formatter formatter = new UpperFormatter();
        Console.WriteLine(formatter.Format("  Time Clock  "));

        formatter = new LowerFormatter();
        Console.WriteLine(formatter.Format("  Time Clock  "));
    }
}

public abstract class Formatter
{
    public abstract string Format(string value);
    protected static string Normalize(string value) => value.Trim();
}

public sealed class UpperFormatter : Formatter
{
    public override string Format(string value) => Normalize(value).ToUpperInvariant();
}

public sealed class LowerFormatter : Formatter
{
    public override string Format(string value) => Normalize(value).ToLowerInvariant();
}

